#!/usr/bin/python3
"""Evaluate saved guest command-mode observations after all statuses persisted."""
import json,os,sys,uuid
from pathlib import Path
H=Path('/tmp/parity-home');C=Path('/tmp/parity-case')
if os.getuid()!=2000 or os.geteuid()!=2000 or Path.cwd()!=C or os.environ.get('HOME')!=str(H): raise SystemExit(125)
if Path('/sys/class/dmi/id/sys_vendor').read_text().strip()!='QEMU': raise SystemExit(125)
try: uuid.UUID(Path('/etc/bashos-parity-vm').read_text().strip())
except (OSError,ValueError): raise SystemExit(125)
def read(n): return (H/n).read_text()
try:
    before=json.loads(read('cmd-before.json'));after=json.loads(read('cmd-after.json'));child=json.loads(read('cmd-child.out'))
    checks={'parent_unchanged':before==after,'child_clamps':(child['attr']['util_min'],child['attr']['util_max'])==(100,800),'argv':child['argv']==['a b',''],'child_status':read('cmd-child.status')=='7\n','child_stderr':read('cmd-child.err')=='','missing_status':read('cmd-missing.status')=='127\n','missing_diagnostic':bool(read('cmd-missing.err')),'builtin_status':read('cmd-builtin.status')=='0\n','builtin_output':read('cmd-builtin.out')=='builtin result\n','builtin_stderr':read('cmd-builtin.err')==''}
except (OSError,ValueError,KeyError) as exc:
    (H/'cmd-check.json').write_text(json.dumps({'incomplete':str(exc)})+'\n');sys.exit(125)
(H/'cmd-check.json').write_text(json.dumps(checks,sort_keys=True)+'\n')
if not all(checks.values()):sys.exit(1)
print('uclamp command checks ok')
